using Microsoft.Data.SqlClient;using System.Data;
namespace KaraokeManager.DAL;
public sealed class KaraokeRepository
{
 public DataTable Rooms(){using var c=Db.Open();using var d=new SqlDataAdapter("SELECT p.MaPhong,p.TenPhong,p.LoaiPhong,p.GiaTheoGio,p.TrangThai,h.MaHD,h.GioVao FROM PhongHat p LEFT JOIN HoaDon h ON h.MaPhong=p.MaPhong AND h.TrangThai=0 ORDER BY p.MaPhong",c);var t=new DataTable();d.Fill(t);return t;}
 public DataTable Services(){using var c=Db.Open();using var d=new SqlDataAdapter("SELECT MaDV,TenDV,DonGia,TonKho FROM DichVu ORDER BY TenDV",c);var t=new DataTable();d.Fill(t);return t;}
 public void SaveService(int? id,string name,decimal price,int stock){using var c=Db.Open();using var x=new SqlCommand(id is null?"INSERT DichVu(TenDV,DonGia,TonKho) VALUES(@n,@p,@s)":"UPDATE DichVu SET TenDV=@n,DonGia=@p,TonKho=@s WHERE MaDV=@id",c);x.Parameters.Add("@n",SqlDbType.NVarChar,100).Value=name;x.Parameters.Add("@p",SqlDbType.Decimal).Value=price;x.Parameters.Add("@s",SqlDbType.Int).Value=stock;if(id!=null)x.Parameters.Add("@id",SqlDbType.Int).Value=id;x.ExecuteNonQuery();}
 public int OpenRoom(int room){using var c=Db.Open();using var tr=c.BeginTransaction();try{using(var check=new SqlCommand("SELECT TrangThai FROM PhongHat WITH(UPDLOCK,HOLDLOCK) WHERE MaPhong=@r",c,tr)){check.Parameters.Add("@r",SqlDbType.Int).Value=room;if(Convert.ToString(check.ExecuteScalar())!="Trống")throw new InvalidOperationException("Phòng đang được sử dụng.");}int id;using(var x=new SqlCommand("INSERT HoaDon(MaPhong,GioVao,TrangThai) VALUES(@r,GETDATE(),0); UPDATE PhongHat SET TrangThai=N'Đang hát' WHERE MaPhong=@r; SELECT CAST(SCOPE_IDENTITY() AS int)",c,tr)){x.Parameters.Add("@r",SqlDbType.Int).Value=room;id=(int)x.ExecuteScalar()!;}tr.Commit();return id;}catch{tr.Rollback();throw;}}
 public int? ActiveInvoice(int room){using var c=Db.Open();using var x=new SqlCommand("SELECT MaHD FROM HoaDon WHERE MaPhong=@r AND TrangThai=0",c);x.Parameters.Add("@r",SqlDbType.Int).Value=room;var o=x.ExecuteScalar();return o is null?null:Convert.ToInt32(o);}
 public DataTable LoadServiceTable(int bill){using var c=Db.Open();using var d=new SqlDataAdapter("SELECT MaHD,MaDV,SoLuong,DonGia FROM ChiTietDichVu WHERE MaHD=@id",c);d.SelectCommand!.Parameters.Add("@id",SqlDbType.Int).Value=bill;d.MissingSchemaAction=MissingSchemaAction.AddWithKey;var t=new DataTable();d.Fill(t);if(t.PrimaryKey.Length==0)t.PrimaryKey=new[]{t.Columns["MaHD"]!,t.Columns["MaDV"]!};return t;}
 public int SaveServiceTable(DataTable table){using var c=Db.Open();using var d=new SqlDataAdapter("SELECT MaHD,MaDV,SoLuong,DonGia FROM ChiTietDichVu WHERE 1=0",c);d.MissingSchemaAction=MissingSchemaAction.AddWithKey;using var builder=new SqlCommandBuilder(d);d.UpdateCommand=builder.GetUpdateCommand();d.InsertCommand=builder.GetInsertCommand();d.DeleteCommand=builder.GetDeleteCommand();return d.Update(table);}
 public void AddService(DataTable table,int bill,int service,int quantity,decimal price){var row=table.Rows.Find(new object[]{bill,service});if(row is null)table.Rows.Add(bill,service,quantity,price);else row["SoLuong"]=Convert.ToInt32(row["SoLuong"])+quantity;}
 public DataTable ServiceNames(){using var c=Db.Open();using var d=new SqlDataAdapter("SELECT MaDV,TenDV,DonGia,TonKho FROM DichVu ORDER BY TenDV",c);var t=new DataTable();d.Fill(t);return t;}
 public void Checkout(int room){using var c=Db.Open();using var tr=c.BeginTransaction();try{int bill;using(var x=new SqlCommand("SELECT MaHD FROM HoaDon WITH(UPDLOCK,HOLDLOCK) WHERE MaPhong=@r AND TrangThai=0",c,tr)){x.Parameters.Add("@r",SqlDbType.Int).Value=room;var o=x.ExecuteScalar();if(o is null)throw new InvalidOperationException("Phòng không có hóa đơn đang mở.");bill=Convert.ToInt32(o);}int lines;using(var x=new SqlCommand("SELECT COUNT(*) FROM ChiTietDichVu WHERE MaHD=@id",c,tr)){x.Parameters.Add("@id",SqlDbType.Int).Value=bill;lines=Convert.ToInt32(x.ExecuteScalar());}int changed;using(var x=new SqlCommand("UPDATE d SET TonKho=d.TonKho-ct.SoLuong FROM DichVu d JOIN ChiTietDichVu ct ON ct.MaDV=d.MaDV WHERE ct.MaHD=@id AND d.TonKho>=ct.SoLuong",c,tr)){x.Parameters.Add("@id",SqlDbType.Int).Value=bill;changed=x.ExecuteNonQuery();}if(changed!=lines)throw new InvalidOperationException("Tồn kho dịch vụ không đủ; thanh toán đã rollback.");using(var x=new SqlCommand("UPDATE h SET GioRa=@now,TongTienPhong=((DATEDIFF(MINUTE,h.GioVao,@now)+59)/60.0)*p.GiaTheoGio,TongTienDichVu=COALESCE((SELECT SUM(SoLuong*DonGia) FROM ChiTietDichVu WHERE MaHD=@id),0),TrangThai=1 FROM HoaDon h JOIN PhongHat p ON p.MaPhong=h.MaPhong WHERE h.MaHD=@id; UPDATE PhongHat SET TrangThai=N'Trống' WHERE MaPhong=@r",c,tr)){x.Parameters.Add("@now",SqlDbType.DateTime).Value=DateTime.Now;x.Parameters.Add("@id",SqlDbType.Int).Value=bill;x.Parameters.Add("@r",SqlDbType.Int).Value=room;x.ExecuteNonQuery();}tr.Commit();}catch{tr.Rollback();throw;}}
 public DataTable Invoices(){using var c=Db.Open();using var d=new SqlDataAdapter("SELECT h.MaHD,p.TenPhong,h.GioVao,h.GioRa,h.TongTienPhong,h.TongTienDichVu,h.TongTienPhong+h.TongTienDichVu AS TongCong,h.TrangThai FROM HoaDon h JOIN PhongHat p ON p.MaPhong=h.MaPhong ORDER BY h.MaHD DESC",c);var t=new DataTable();d.Fill(t);return t;}
 public DataTable RoomServiceNames(int bill){using var c=Db.Open();using var d=new SqlDataAdapter("SELECT c.MaDV,d.TenDV,c.SoLuong,c.DonGia,c.SoLuong*c.DonGia AS ThanhTien FROM ChiTietDichVu c JOIN DichVu d ON d.MaDV=c.MaDV WHERE c.MaHD=@id",c);d.SelectCommand!.Parameters.Add("@id",SqlDbType.Int).Value=bill;var t=new DataTable();d.Fill(t);return t;}
 public int Scalar(string sql){using var c=Db.Open();using var x=new SqlCommand(sql,c);return Convert.ToInt32(x.ExecuteScalar()??0);}
}